export const MARK_CONTENT_RATIO = 0.927;
export const MARK_CONTENT_SIZE = 1390.5;

/** Scale that makes the standalone mark match the wordmark's crescent. */
export const MARK_END_SCALE = 189.2 / MARK_CONTENT_SIZE;

