type Art = 'markFull' | 'markTight' | 'wordmarkFull' | 'wordmarkTight';

const SOURCE: Record<Art, string> = {
  markFull: MARK_FULL,
  markTight: MARK_TIGHT,
  wordmarkFull: WORDMARK_FULL,
  wordmarkTight: WORDMARK_TIGHT,
};

/**
 * Tinted copies are cached: the strings are tens of kilobytes and `SvgXml`
 * re-parses whenever the XML it is handed changes identity, so recolouring on
 * every render would be wasteful twice over.
 */
const cache = new Map<string, string>();

function tinted(art: Art, color: string): string {
  const key = art + '|' + color;
  const hit = cache.get(key);
  if (hit) return hit;
  const xml = SOURCE[art].split('#ffffff').join(color);
  cache.set(key, xml);
  return xml;
}

/** The crescent on its original square canvas. For the splash, where coordinates matter. */
export const markFull = (color: string) => tinted('markFull', color);
/** The crescent cropped to itself. For icons and badges. */
export const markTight = (color: string) => tinted('markTight', color);
/** The wordmark on its original square canvas. */
export const wordmarkFull = (color: string) => tinted('wordmarkFull', color);
/** The wordmark cropped to itself. Use with `WORDMARK_ASPECT`. */
export const wordmarkTight = (color: string) => tinted('wordmarkTight', color);
